import React, { useState, useEffect, useCallback, useRef, useContext } from 'react';

import { styled } from '@mui/material/styles';
import { useSearchParams } from 'react-router-dom';
import {
  Container,
  Typography,
  Box,
  CircularProgress,
  Button,
  useTheme,
  useMediaQuery,
  Grid
} from '@mui/material';
import { Refresh as RefreshIcon, FilterList as FilterListIcon, FilterListOff as FilterListOffIcon } from '@mui/icons-material';
import TextField from '@mui/material/TextField';
import MenuItem from '@mui/material/MenuItem';
import InputAdornment from '@mui/material/InputAdornment';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import 'date-fns';
import NewsWidget from '../components/NewsWidget';
import { NEWS_SECTIONS } from '../components/NewsWidget';
import { useAuth } from '../context/AuthContext';
import AlertContext from '../context/alert/alertContext';
import WeatherWidget from '../components/WeatherWidget';
import { useDispatch, useSelector } from 'react-redux';
import { fetchTopHeadlines, getFallbackNews } from '../services/newsService';
import { fetchPosts, selectAllPosts } from '../features/community/communitySlice';

// Styled components
const HeaderSection = styled(Box)(({ theme }) => ({
  background: 'linear-gradient(135deg, #0d4d8d 0%, #032e6e 100%)',
  color: theme.palette.common.white,
  padding: theme.spacing(4, 0),
  position: 'relative',
  minHeight: '350px',
  minWidth: '450px',
  display: 'flex',
  alignItems: 'center',
  width: '100%',
  borderRadius: '16px',
  overflow: 'hidden',
  marginBottom: theme.spacing(4),
  [theme.breakpoints.down('sm')]: {
    padding: 0,
  }
}));

const WeatherWidgetContainer = styled(Box)(({ theme }) => ({
  position: 'absolute',
  top: '50%',
  right: 24,
  transform: 'translateY(-50%)',
  zIndex: 1,
  minHeight: '220px',
  minWidth: '280px',
  backdropFilter: 'blur(8px)',
  backgroundColor: 'rgba(255, 255, 255, 0.15)',
  borderRadius: '12px',
  padding: theme.spacing(2),
  border: '1px solid rgba(255, 255, 255, 0.2)',
  boxShadow: '0 4px 20px rgba(0, 0, 0, 0.15)',
  [theme.breakpoints.down('lg')]: {
    position: 'relative',
    right: 0,
    top: 0,
    transform: 'none',
    marginTop: theme.spacing(3),
    width: '100%',
    minHeight: '200px',
  },
  [theme.breakpoints.down('sm')]: {
    minHeight: 'auto',
    marginTop: theme.spacing(2),
  },
}));

// Get the current time of day for a personalized greeting
const getGreeting = (user) => {
  const hour = new Date().getHours();
  let greeting = '';
  
  if (hour < 12) greeting = 'Good morning';
  else if (hour < 18) greeting = 'Good afternoon';
  else greeting = 'Good evening';
  
  if (user?.username) {
    const firstName = user.username.split(' ')[0];
    return `${greeting}, ${firstName}`;
  }
  
  return greeting;
};

const Dashboard = () => {
  const [searchParams] = useSearchParams();
  const categoryFromUrl = searchParams.get('category') || 'breaking';

  // State management
  const [loading, setLoading] = useState(true);
  const [news, setNews] = useState([]);
  const [error, setError] = useState(null);
  const [filters, setFilters] = useState({
    country: 'us',
    category: categoryFromUrl,
    fromDate: null,
    toDate: null,
  });
  
  const [showFilters, setShowFilters] = useState(false);
  
  // Available countries for the dropdown
  const countries = [
    { code: 'us', name: 'United States' },
    { code: 'gb', name: 'United Kingdom' },
    { code: 'ca', name: 'Canada' },
    { code: 'au', name: 'Australia' },
    { code: 'in', name: 'India' },
  ];
  
  // Refs for request tracking
  const controllerRef = useRef(null);
  const isMounted = useRef(true);
  
  // Context and hooks
  const auth = useAuth();
  const { user } = auth;
  const { setAlert } = useContext(AlertContext);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const dispatch = useDispatch();
  const isAuthenticated = useSelector((state) => state.auth.isAuthenticated);
  const posts = useSelector(selectAllPosts);

  // Handle filter changes with debounce
  const handleFilterChange = useCallback((newFilters) => {
    // Update the filters state
    setFilters(prevFilters => {
      const updatedFilters = { ...prevFilters, ...newFilters };
      
      // If category changes, we need to update the URL
      if (newFilters.category && newFilters.category !== prevFilters.category) {
        const section = Object.values(NEWS_SECTIONS).find(
          s => s.apiCategory === newFilters.category
        );
        if (section && section.id) {
          // Update URL without page reload
          const searchParams = new URLSearchParams(window.location.search);
          searchParams.set('category', section.id);
          window.history.pushState({}, '', `${window.location.pathname}?${searchParams}`);
        }
      }
      
      return updatedFilters;
    });
    
    // Only trigger API call if we're not already loading
    if (!loading) {
      setLoading(true);
      
      // Cancel any pending requests
      if (controllerRef.current) {
        controllerRef.current.abort();
      }
      
      // Create a new controller for this request
      controllerRef.current = new AbortController();
      
      // Debounce the API call
      const timer = setTimeout(() => {
        fetchNews(newFilters);
      }, 500);
      
      // Cleanup function
      return () => {
        clearTimeout(timer);
        if (controllerRef.current) {
          controllerRef.current.abort();
        }
      };
    }
  }, [loading]);

  // Format date for API
  const formatDateForApi = (date) => {
    if (!date) return null;
    return new Date(date).toISOString().split('T')[0]; // YYYY-MM-DD format
  };

  // Fetch news when filters change with error handling and fallback
  const fetchNews = useCallback(async (filterOverrides = {}) => {
    if (!isMounted.current) {
      console.log('Component unmounted, skipping fetch');
      return;
    }
    
    setLoading(true);
    
    try {
      const sectionFromUrl = searchParams.get('category') || 'breaking';
      const section = NEWS_SECTIONS.find(s => s.id === sectionFromUrl) || NEWS_SECTIONS[0];
      
      // Merge filters from props and overrides
      const activeFilters = {
        ...filters,
        ...filterOverrides,
        // Ensure we have a valid category
        category: filterOverrides.category || filters.category || section?.apiCategory || 'general'
      };
      
      // Map 'breaking' to 'general' for the API call
      if (activeFilters.category === 'breaking') {
        activeFilters.category = 'general';
      }
      
      // If we have a previous error about rate limiting, use fallback data
      if (error?.includes('too many requests') || error?.includes('rate limit')) {
        console.log('Using fallback data due to rate limiting');
        setNews(getFallbackNews(activeFilters.category, 12));
        setLoading(false);
        return;
      }
      
      const signal = controllerRef.current?.signal;
      console.log(`Fetching ${activeFilters.category} news...`);
      
      // Prepare API parameters
      const params = {
        category: activeFilters.category,
        country: activeFilters.country || 'us',
        pageSize: 12,
        page: 1
      };
      
      // Add date filters if provided
      if (activeFilters.fromDate) {
        params.from = formatDateForApi(activeFilters.fromDate);
      }
      if (activeFilters.toDate) {
        params.to = formatDateForApi(activeFilters.toDate);
      }
      
      const articles = await fetchTopHeadlines(params, signal);
      
      if (!isMounted.current) return;
      
      // Format articles with fallbacks for missing data
      const formattedArticles = (articles || []).map(article => ({
        id: article.url || `article-${Math.random().toString(36).substr(2, 9)}`,
        title: article.title || 'No title available',
        description: article.description || 'No description available',
        url: article.url || '#',
        urlToImage: article.image || article.urlToImage || 'https://via.placeholder.com/400x200?text=No+Image',
        publishedAt: article.publishedAt || new Date().toISOString(),
        source: { 
          name: article.source?.name || article.sourceName || 'Unknown Source' 
        },
        content: article.content || article.description || ''
      }));
      
      if (isMounted.current) {
        setNews(formattedArticles);
        setError(null);
      }
    } catch (err) {
      if (err.name !== 'AbortError') {
        console.error('Error in fetchNews:', err);
        if (isMounted.current) {
          setError('Failed to load news. Using fallback data.');
          // Explicitly set fallback news
          setNews(getFallbackNews('general', 12));
        }
      }
    } finally {
      if (isMounted.current) {
        setLoading(false);
      }
    }
  }, [searchParams, error]);

  // Initial data fetch and component mount
  useEffect(() => {
    isMounted.current = true;
    
    // Fetch initial news
    const section = searchParams.get('category') || 'breaking';
    const sectionObj = NEWS_SECTIONS.find(s => s.id === section) || NEWS_SECTIONS[0];
    const category = sectionObj.apiCategory || 'general';
    
    setFilters(prev => ({
      ...prev,
      category: category
    }));
    
    fetchNews({ category });
    
    // Fetch posts if authenticated
    if (isAuthenticated) {
      dispatch(fetchPosts());
    }
    
    return () => {
      isMounted.current = false;
      if (controllerRef.current) {
        controllerRef.current.abort();
      }
    };
  }, [searchParams, isAuthenticated, dispatch, fetchNews]);

  return (
    <Box sx={{ width: '100%', overflowX: 'hidden' }}>
      <HeaderSection>
        <Container maxWidth="xl" sx={{ position: 'relative', zIndex: 1, padding: { xs: 2, md: 3 } }}>
          <Grid container spacing={2} alignItems="center">
            <Grid item xs={12} md={8} lg={9}>
              <Box>
                <Typography variant="h3" component="h1" gutterBottom sx={{ 
                  fontSize: { xs: '1.8rem', sm: '2.2rem', md: '2.5rem' },
                  color: 'white',
                  mb: 2
                }}>
                  {getGreeting(user)}
                </Typography>
                <Box>
                  <Button
                    variant="contained"
                    color="secondary"
                    onClick={() => handleFilterChange({})}
                    disabled={loading}
                    startIcon={loading ? <CircularProgress size={20} /> : <RefreshIcon />}
                    sx={{ 
                      backgroundColor: 'rgba(255, 255, 255, 0.1)',
                      color: 'white',
                      '&:hover': {
                        backgroundColor: 'rgba(255, 255, 255, 0.2)',
                        border: '1px solid rgba(255, 255, 255, 0.3)',
                      }
                    }}
                  >
                    {loading ? 'Refreshing...' : 'Refresh News'}
                  </Button>
                </Box>
              </Box>
            </Grid>
            
            <Grid item xs={12} md={4} lg={3}>
              {!isMobile && (
                <WeatherWidgetContainer>
                  <WeatherWidget />
                </WeatherWidgetContainer>
              )}
            </Grid>
          </Grid>
        </Container>
      </HeaderSection>

      <Container maxWidth="xl" sx={{ mt: 4, mb: 6, px: { xs: 2, sm: 3 } }}>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            {isMobile && <WeatherWidget />}
            <NewsWidget
              news={news}
              loading={loading}
              error={error}
              activeSection={filters.category}
              onSectionChange={(section) => handleFilterChange({ category: section })}
              cardProps={{
                sx: {
                  '& .MuiCard-root': {
                    height: '100%',
                    display: 'flex',
                    flexDirection: 'column',
                    transition: 'transform 0.2s ease-in-out',
                    '&:hover': {
                      transform: 'translateY(-4px)',
                      boxShadow: 3,
                    },
                  },
                  '& .MuiCardContent': {
                    flexGrow: 1,
                    display: 'flex',
                    flexDirection: 'column',
                    p: 2.5,
                  },
                  '& .MuiCardMedia-root': {
                    height: 200,
                    objectFit: 'cover',
                  },
                },
              }}
              gridProps={{
                container: { spacing: 3 },
                item: { xs: 12, sm: 6, lg: 4 },
              }}
              sx={{
                '& .MuiTabs-scroller': {
                  overflow: 'auto !important',
                  '&::-webkit-scrollbar': {
                    height: '6px',
                  },
                  '&::-webkit-scrollbar-thumb': {
                    backgroundColor: 'rgba(0,0,0,0.2)',
                    borderRadius: '3px',
                  },
                },
              }}
            />
          </Grid>
        </Grid>
      </Container>
    </Box>
  );
};

export default Dashboard;
